-- Restores hidden/child data for the remaining orphaned Pathfinder creatures not covered by
-- restore_orphaned_creature_data_from_4_1_0.sql (which used the v4.1.0 snapshot). These 138
-- creatures had no data in 4.1.0 either, but are recoverable from the older v4.0.0 sqlite
-- snapshot (github.com/RakuJa/BYBE-DB releases). Restoration is keyed on foundry_id, never
-- on old row ids.

-- ==== Beetle Carapace (T9osQMcC96l4X9lk) ====
DO $mig$
DECLARE
  cr_id bigint;
  v_item_id bigint;
  v_sce_id bigint;
  v_range_id bigint;
  v_sense_id bigint;
  v_weakness_id bigint;
  v_resistance_id bigint;
  v_skill_id bigint;
  v_action_id bigint;
  v_spell_id bigint;
  v_weapon_id bigint;
  v_armor_id bigint;
  v_shield_id bigint;
BEGIN
  SELECT id INTO cr_id FROM pf_creature_table WHERE foundry_id = 'T9osQMcC96l4X9lk';
  IF cr_id IS NULL THEN RETURN; END IF;

<hr />
<p><p>The monster deals the listed amount of damage to any number of creatures Grabbed or Restrained by it. Each of those creatures can attempt a basic Fortitude save with the listed DC.</p></p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'constrict', 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
  BEGIN
  EXCEPTION WHEN unique_violation THEN NULL;
  END;
  SELECT id INTO v_item_id FROM pf_item_table WHERE foundry_id = '7wp3tf6myiuh5zf6';
  IF v_item_id IS NULL THEN SELECT id INTO v_item_id FROM pf_item_table WHERE name = 'Mandible' ORDER BY id LIMIT 1; END IF;
  BEGIN
  EXCEPTION WHEN unique_violation THEN NULL;
  END;
  SELECT id INTO v_item_id FROM pf_item_table WHERE foundry_id = 'drfXFnc49cl52C2X';
  IF v_item_id IS NULL THEN SELECT id INTO v_item_id FROM pf_item_table WHERE name = 'Foot' ORDER BY id LIMIT 1; END IF;
END $mig$;

-- ==== Graveknight Warmaster (Yv9e7NSCzPuhlCnH) ====
DO $mig$
DECLARE
  cr_id bigint;
  v_item_id bigint;
  v_sce_id bigint;
  v_range_id bigint;
  v_sense_id bigint;
