-- ==== Moon Hag (qm0YqO9ik2U2Gjdx) ====
DO $mig$
DECLARE
  cr_id bigint;
  v_item_id bigint;
  v_sce_id bigint;
  v_range_id bigint;
  v_sense_id bigint;
