  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Hungry Armor', 'passive', NULL, 'defensive', '<p>A creature that Strikes a graveknight warmaster with a melee weapon must succeed at a DC 31 save or be disarmed of that weapon. If the creature critically fails, the weapon ends up in the graveknight''s space. A creature that hits a graveknight warmaster with an unarmed attack must succeed at a DC 31 or become Grabbed by the graveknight until the end of its next turn, it Escapes, or the graveknight moves, whichever comes first.</p>', 'OGL', FALSE, '', NULL, 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
