  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Drain Magic', 'action', 1, 'defensive', '<p><strong>Requirements</strong> The vanyver''s last action was a successful jaws Strike against a creature, object, or spell effect</p>
