  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Entropy''s Shadow', 'passive', NULL, 'defensive', '<p>40 feet. Vanyvers leak entropy and corruption from their very being. A living creature entering or starting its turn in the aura takes 3d6 void damage with a DC 30. If it fails, it''s also Enfeebled 1 for 1 minute and pulled 10 feet toward the vanyver.</p>', 'OGL', FALSE, '', NULL, 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
