  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Snatch', 'passive', NULL, 'defensive', '<p>The vanyver can Fly at half Speed while they have a creature Grabbed or Restrained in either or both of their talons, carrying that creature along with them.</p>', 'OGL', FALSE, '', NULL, 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
