  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('+1 Status to All Saves vs. Vitality', 'passive', NULL, 'defensive', '', 'OGL', FALSE, '', '1-status-to-all-saves-vs-magic', 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
