  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Magma Tomb', 'action', 2, 'offensive', '<p>Once per day, the dragon can spit a molten boulder at a target within 120 feet. This deals 12d6 fire damage and 5d12 bludgeoning damage, with a DC 42 save. If the creature fails its save, it''s encased in magma that instantly cools and has Hardness 10, HP 40, and BT 20. The encased creature can''t breathe and is Restrained (/act escape dc=42).</p>', 'OGL', FALSE, '', NULL, 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
