  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Whispering Wounds', 'passive', NULL, 'defensive', '<p>30 feet. When a creature ends its turn in the aura, it hears the wounds on the ostiarius''s body whisper obscene truths. The creature must succeed at a DC 21 save or become Sickened 1.</p>', 'OGL', FALSE, '', NULL, 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
