  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Gemsight', 'passive', NULL, 'interaction', '<p>As long as the stygira holds a gemstone, they can see through the gem with Darkvision and the effects of Truesight. The stygira is Blinded when they are not holding a gem in a hand.</p>', 'OGL', FALSE, '', NULL, 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
