  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Stone Curse', 'passive', NULL, 'offensive', '<p>Wounds dealt by the stygira''s claws leave the flesh bleached of color and turn the blood that runs from them dark gray. Each time a creature is damaged by the stygira''s claw Strike, it must succeed at a DC 25 save or become permanently Slowed 1 (slowed 2 on a critical failure) as its flesh stiffens like stone. If a creature is reduced to 0 Hit Points from the stygira''s claw Strike and fails the saving throw against stone curse, it is Petrified. A creature that spends 8 hours in direct sunlight can attempt a new saving throw to remove the effects of stone curse, even if it has been petrified.</p>', 'OGL', FALSE, '', 'stone-curse', 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
