  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Necrotic Decay', 'passive', NULL, 'defensive', '<p>When an urdefhan dies, its invisible flesh quickly rots away and sublimates into a foul-smelling gas that fills a 5-foot  around the body.</p>
  INSERT INTO pf_trait_table (name) VALUES ('divine') ON CONFLICT DO NOTHING;
