  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Wicked Bite', 'action', 1, 'offensive', '<p><strong>Requirements</strong> The urdefhan damaged a creature with a jaws Strike on its last action</p><hr /><p><strong>Effect</strong> The urdefhan maintains contact, turning the creature''s flesh translucent around the site of the injury. The urdefhan chooses one of two options, each of which requires a DC 22 save. If the jaws Strike was a critical hit, the creature suffers both effects, using the same save result for both.</p><ul><li><strong>Drain Blood</strong> The urdefhan drinks some of the creature''s blood. On a failed save, the creature is Drained 1 and the urdefhan regains 5 healing HP (or, on a critical failure, it''s Drained 2 and the urdefhan regains 10 healing HP).</li><li><strong>Drain Vitality</strong> The urdefhan draws out some of the creature''s vital essence. The creature becomes Enfeebled 1 for 1 hour on a failed save (or Enfeebled 2 for 1 hour on a critical failure).</li></ul>', 'OGL', FALSE, '', 'wicked-bite', 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
