  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Drain Blood', 'action', 1, 'offensive', '<p><strong>Requirements</strong> A Grabbed, Paralyzed, Restrained, Unconscious, or willing creature is within the blood hag''s reach</p><hr /><p><strong>Effect</strong> The hag sinks her fangs into the creature to drink its blood. This requires a successful  check against the victim''s Fortitude DC if the victim is grabbed and is automatic for any of the other conditions.</p>
