  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Breath Weapon', 'action', 2, 'offensive', '<p>The draconal breathes a blast of energy that deals 21d6 cold damage to creatures they choose to damage in a 60-foot  (DC 44 save).</p>
