  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Dragon''s Salvation', 'reaction', NULL, 'defensive', '<p><strong>Trigger</strong> A creature within the draconal''s reach would take damage.</p>
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Breath Weapon', 'action', 2, 'offensive', '<p>The draconal breathes a blast of energy that deals 21d6 acid damage to creatures they choose to damage in a 60-foot  (DC 44 save).</p>
