  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Easy to Call', 'passive', NULL, 'interaction', '<p>A esipil''s level is considered 2 lower for the purpose of being conjured by the Binding Circle ritual (and potentially other rituals, at the GM''s discretion), but it is always free to attack or leave instead of negotiate unless the primary caster''s check is a critical success.</p>', 'OGL', FALSE, '', NULL, 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
