  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Change Shape', 'action', 1, 'offensive', '<p>The esipil transforms into a Tiny cat, dog, or other unassuming domestic animal. This doesn''t affect the esipil''s statistics, but it could change the damage type of its Strikes.</p>
