  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Woodland Stride', 'passive', NULL, 'offensive', '<p>The forest dragon ignores difficult terrain and greater difficult terrain from non-magical foliage.</p>', 'OGL', FALSE, '', NULL, 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
