  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Light Blindness', 'passive', NULL, 'defensive', '<p><p>When first exposed to bright light, the monster is Blinded until the end of its next turn. After this exposure, light doesn''t blind the monster again until after it spends 1 hour in darkness. However, as long as the monster is in an area of bright light, it''s Dazzled.</p></p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'light-blindness', 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
