  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Tied to the Land', 'passive', NULL, 'interaction', '<p>A hesperid queen is intrinsically tied to a isolated region, usually an island or island chain, a remote coast, or secluded valley. As long as the queen is healthy, the environment is exceptionally resilient, allowing the hesperid queen to automatically attempt to counteract spells and rituals such as Blight that would harm the environment, with a +37 counteract modifier and a counteract rank of 10.</p>
  INSERT INTO pf_creature_action_association_table (creature_id, action_id) VALUES (cr_id, v_action_id) ON CONFLICT DO NOTHING;
  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Nymph''s Beauty', 'passive', NULL, 'defensive', '<p>30 feet. Creatures that start their turn in the aura must succeed at a DC 38 save or become transfixed in awe, causing them to be Stunned for 1 round.</p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'nymph-queen-nymphs-beauty', 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
