  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Change Shape', 'action', 1, 'offensive', '<p>Hesperid queens can transform between their original form, which looks much like a typical nymph of their kind, and any Small or Medium humanoid form, typically choosing a version of their natural form that more closely resembles a humanoid.</p>
  INSERT INTO pf_trait_table (name) VALUES ('polymorph') ON CONFLICT DO NOTHING;
