  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Focus Beauty', 'action', 1, 'offensive', '<p>The hesperid queen focuses her beauty upon a target within her aura. The creature must attempt a DC 38 save. On a failure, it is affected as if by the hesperid queen''s nymph''s beauty aura; if it was already affected by the aura, it becomes overwhelmed with visions of bliss and beauty. The creature departs from the hesperid queen''s domain as quickly and efficiently as it can for 1 hour, after which time it forgets ever reaching the hesperid queen''s domain, how it did so, and everything that happened while it was within the domain.</p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'nymph-queen-focus-beauty', 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
