  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Sunset Dependent', 'passive', NULL, 'defensive', '<p>A hesperid is mystically bonded to a single remote location with a good view of the sunset-usually an island, coastal cliff, or valley. If they aren''t at that location and able to see the sky at sunset on any given day, they become Drained 1, increasing the value by 1 for each missed sunset and reducing by 1 only when they see the sunset.</p>
