  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Cavern Empathy', 'passive', NULL, 'interaction', '<p>The lampad queen can use Diplomacy to /act make-an-impression on and make very simple Requests of subterranean animals, plants, and fungi, as well as stones.</p>', 'OGL', FALSE, '', NULL, 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
