  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Nymph''s Beauty', 'passive', NULL, 'defensive', '<p>30 feet. Creatures that start their turn in the aura must succeed at a DC 33 save or be Confused by the lampad queen''s unearthly beauty for 1 minute. While confused by this effect, the creature''s confused actions never include harming the lampad queen.</p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'nymph-queen-nymphs-beauty', 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
