  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Clever Disguises', 'passive', NULL, 'offensive', '<p>A mi-go can use Deception to Impersonate any Medium humanoid creature, although creating such a disguise takes 1 hour. It can''t impersonate a specific individual with this ability.</p>', 'OGL', FALSE, '', NULL, 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
