  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Eviscerate', 'action', 1, 'offensive', '<p>The mi-go performs a swift and painful surgery on a creature it has Grabbed or Restrained or that is otherwise Immobilized, attempting a  check against the target''s Fortitude DC. Regardless of the result, the target then becomes temporarily immune for 24 hours.</p>
  INSERT INTO pf_trait_table (name) VALUES ('manipulate') ON CONFLICT DO NOTHING;
