  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Sneak Attack', 'passive', NULL, 'offensive', '<p>A mi-go deals an extra 1d6 precision damage to Off-Guard creatures.</p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'sneak-attack', 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
