  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Change Shape', 'action', 1, 'offensive', '<p>The nosferatu transforms into a swarm of pale-gray rats. They gain a land Speed of 30 feet and a climb Speed of 10 feet, and they become Large. Each enemy in the swarm''s space takes 2d10 piercing damage and must attempt a DC 36 save with a high DC for the creature''s level. A creature that fails its save is exposed to plague of ancients.</p>
