  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Dominate', 'action', 2, 'offensive', '<p>The nosferatu can cast Dominate at will as a divine innate spell. Casting it requires staring into the target''s eyes, giving the spell the visual trait (DC 36). The save DC uses a high DC for the nosferatu''s level, and a creature that succeeds is temporarily immune to that nosferatu''s Dominate for 24 hours. Fully destroying the nosferatu ends the domination, but merely reducing the nosferatu to 0 HP is insufficient to break the spell.</p>', 'OGL', FALSE, 'Pathfinder Bestiary 3', 'vampire-nosferatu-dominate', 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
