  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Wavesense (Imprecise) 60 feet', 'passive', NULL, 'interaction', '<p><p>This sense allows a monster to feel vibrations caused by movement through a liquid. It''s an imprecise sense with a limited range (listed in the ability). Wavesense functions only if monster and the subject are in the same body of liquid, and only if the subject is moving through the liquid.</p></p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'wavesense', 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
