  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Grab', 'action', 1, 'offensive', '<p><p><strong>Requirements</strong> The monster''s last action was a successful Strike that lists Grab in its damage entry, or the monster has a creature Grabbed or Restrained</p><hr /><p><strong>Effect</strong> If used after a Strike, the monster attempts to /act grapple the creature using the body part it attacked with. This attempt neither applies nor counts toward the creature''s multiple attack penalty.</p><p>The monster can instead use Grab and choose one creature it''s grabbing or restraining with an appendage that has Grab to automatically extend that condition to the end of the monster''s next turn.</p></p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'grab', 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
