  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Grave Tide', 'passive', NULL, 'offensive', '<p>The shambler troop is less organized than most troops. It can move into other creatures'' spaces, and other creatures can move into its spaces. Its spaces are difficult terrain to other creatures.</p>', 'OGL', FALSE, '', NULL, 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
