  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Living Machine', 'passive', NULL, 'defensive', '<p>Though their body is an organic construct, a wyrwood is a living creature. They''re not immediately destroyed when reduced to 0 HP, but rather fall Unconscious and eventually die. They don''t need to eat or drink. They can be targeted by effects that target living creatures or that target constructs.</p>', 'OGL', FALSE, '', NULL, 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
