  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Telepathy 100 feet', 'passive', NULL, 'interaction', '<p><p>A monster with telepathy can communicate mentally with any creatures within the listed radius, as long as they share a language. This doesn''t give any special access to their thoughts, and communicates no more information than normal speech would.</p></p>', 'OGL', FALSE, 'Pathfinder Bestiary', 'telepathy', 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
