  INSERT INTO pf_action_table (name, action_type, n_of_actions, category, description, license, remaster, source, slug, rarity) VALUES ('Holy Weaponry', 'passive', NULL, 'offensive', '<p>Any weapon becomes a <em>Striking Holy</em> weapon while the zuishin wields it. A zuishin creates arrows out of nothing as part of their attacks with any bow they wield.</p>', 'OGL', FALSE, '', NULL, 'common') ON CONFLICT (name, action_type, n_of_actions, category, md5(COALESCE(description, '__NULL__')), license, remaster, source, slug, rarity) DO UPDATE SET name = EXCLUDED.name RETURNING id INTO v_action_id;
